  function crc32(bytes) {
    let crc = 0xffffffff;
    for (const byte of bytes) {
      crc ^= byte;
      for (let bit = 0; bit < 8; bit += 1) {
        crc = (crc >>> 1) ^ (0xedb88320 & -(crc & 1));
      }
    }
    return (crc ^ 0xffffffff) >>> 0;
  }

  function zipDateTime(date = new Date()) {
    const year = Math.max(1980, date.getFullYear());
    return {
      time: (date.getHours() << 11) | (date.getMinutes() << 5) | Math.floor(date.getSeconds() / 2),
      date: ((year - 1980) << 9) | ((date.getMonth() + 1) << 5) | date.getDate()
    };
  }

  function concatBytes(parts) {
    const length = parts.reduce((sum, part) => sum + part.length, 0);
    const output = new Uint8Array(length);
    let offset = 0;
    parts.forEach((part) => {
      output.set(part, offset);
      offset += part.length;
    });
    return output;
  }

  async function createStoredZip(files) {
    const encoder = new TextEncoder();
    const localParts = [];
    const centralParts = [];
    let localOffset = 0;
    const stamp = zipDateTime();

    for (const file of files) {
      const name = encoder.encode(file.name);
      const data = new Uint8Array(await file.blob.arrayBuffer());
      const checksum = crc32(data);
      const local = new Uint8Array(30 + name.length);
      const localView = new DataView(local.buffer);
      localView.setUint32(0, 0x04034b50, true);
      localView.setUint16(4, 20, true);
      localView.setUint16(6, 0x0800, true);
      localView.setUint16(8, 0, true);
      localView.setUint16(10, stamp.time, true);
      localView.setUint16(12, stamp.date, true);
      localView.setUint32(14, checksum, true);
      localView.setUint32(18, data.length, true);
      localView.setUint32(22, data.length, true);
      localView.setUint16(26, name.length, true);
      local.set(name, 30);
      localParts.push(local, data);

      const central = new Uint8Array(46 + name.length);
      const centralView = new DataView(central.buffer);
      centralView.setUint32(0, 0x02014b50, true);
      centralView.setUint16(4, 20, true);
      centralView.setUint16(6, 20, true);
      centralView.setUint16(8, 0x0800, true);
      centralView.setUint16(10, 0, true);
      centralView.setUint16(12, stamp.time, true);
      centralView.setUint16(14, stamp.date, true);
      centralView.setUint32(16, checksum, true);
      centralView.setUint32(20, data.length, true);
      centralView.setUint32(24, data.length, true);
      centralView.setUint16(28, name.length, true);
      centralView.setUint32(42, localOffset, true);
      central.set(name, 46);
      centralParts.push(central);
      localOffset += local.length + data.length;
    }

    const centralData = concatBytes(centralParts);
    const end = new Uint8Array(22);
    const endView = new DataView(end.buffer);
    endView.setUint32(0, 0x06054b50, true);
    endView.setUint16(8, files.length, true);
    endView.setUint16(10, files.length, true);
    endView.setUint32(12, centralData.length, true);
    endView.setUint32(16, localOffset, true);
    return new Blob([...localParts, centralData, end], { type: "application/zip" });
  }

  function safeExportName(value) {
    return String(value || "크랙 채팅")
      .replace(/\|\s*크랙.*$/i, "")
      .replace(/[\\/:*?"<>|]/g, "_")
      .replace(/\s+/g, " ")
      .trim()
      .slice(0, 72) || "크랙 채팅";
  }

  function downloadBlob(blob, name) {
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement("a");
    anchor.href = url;
    anchor.download = name;
    anchor.style.display = "none";
    document.body.append(anchor);
    anchor.click();
    anchor.remove();
    setTimeout(() => URL.revokeObjectURL(url), 60000);
  }

  function createAnnotationOverlay(title) {
    document.querySelector(".ucb-annotation-overlay")?.remove();
    const overlay = document.createElement("div");
    overlay.className = "ucb-annotation-overlay";
    const dialog = document.createElement("div");
    dialog.className = "ucb-annotation-dialog";
    dialog.setAttribute("role", "dialog");
    dialog.setAttribute("aria-modal", "true");
    const head = document.createElement("div");
    head.className = "ucb-annotation-head";
    const heading = document.createElement("strong");
    heading.textContent = title;
    const close = document.createElement("button");
    close.type = "button";
    close.className = "ucb-annotation-close";
    close.setAttribute("aria-label", "닫기");
    close.textContent = "×";
    head.append(heading, close);
    dialog.append(head);
    overlay.append(dialog);
    const dismiss = () => overlay.remove();
    close.addEventListener("click", dismiss);
    overlay.addEventListener("pointerdown", (event) => {
      if (event.target === overlay) dismiss();
    });
    document.body.append(overlay);
    return { overlay, dialog, dismiss };
  }

  function annotationButton(label, className = "") {
    const button = document.createElement("button");
    button.type = "button";
    button.className = `ucb-annotation-button ${className}`.trim();
    button.textContent = label;
    return button;
  }

  function wait(milliseconds) {
    return new Promise((resolve) => setTimeout(resolve, milliseconds));
  }

  function waitForIdle() {
    return new Promise((resolve) => {
      if (typeof requestIdleCallback === "function") {
        requestIdleCallback(() => resolve(), { timeout: 350 });
      } else {
        setTimeout(resolve, 220);
      }
    });
  }
  async function inflateZipBytes(bytes) {
    if (typeof DecompressionStream !== "function") {
      throw new Error("압축된 ZIP을 이 브라우저에서 읽을 수 없어요");
    }
    const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream("deflate-raw"));
    return new Uint8Array(await new Response(stream).arrayBuffer());
  }

  async function readZipTextFiles(blob) {
    const bytes = new Uint8Array(await blob.arrayBuffer());
    const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
    let endOffset = -1;
    for (let offset = bytes.length - 22; offset >= Math.max(0, bytes.length - 65557); offset -= 1) {
      if (view.getUint32(offset, true) === 0x06054b50) {
        endOffset = offset;
        break;
      }
    }
    if (endOffset < 0) throw new Error("올바른 ZIP 파일이 아니에요");

    const count = view.getUint16(endOffset + 10, true);
    let centralOffset = view.getUint32(endOffset + 16, true);
    const decoder = new TextDecoder();
    const files = [];
    for (let index = 0; index < count; index += 1) {
      if (centralOffset + 46 > bytes.length || view.getUint32(centralOffset, true) !== 0x02014b50) {
        throw new Error("ZIP 내부 파일 목록이 손상되었어요");
      }
      const method = view.getUint16(centralOffset + 10, true);
      const compressedSize = view.getUint32(centralOffset + 20, true);
      const nameLength = view.getUint16(centralOffset + 28, true);
      const extraLength = view.getUint16(centralOffset + 30, true);
      const commentLength = view.getUint16(centralOffset + 32, true);
      const localOffset = view.getUint32(centralOffset + 42, true);
      const nameStart = centralOffset + 46;
      const name = decoder.decode(bytes.subarray(nameStart, nameStart + nameLength));

      if (localOffset + 30 > bytes.length || view.getUint32(localOffset, true) !== 0x04034b50) {
        throw new Error("ZIP 내부 메모 파일이 손상되었어요");
      }
      const localNameLength = view.getUint16(localOffset + 26, true);
      const localExtraLength = view.getUint16(localOffset + 28, true);
      const dataStart = localOffset + 30 + localNameLength + localExtraLength;
      const compressed = bytes.slice(dataStart, dataStart + compressedSize);
      if (/\.txt$/i.test(name) && !name.endsWith("/")) {
        const data = method === 0 ? compressed : method === 8
          ? await inflateZipBytes(compressed)
          : null;
        if (!data) throw new Error(`지원하지 않는 ZIP 압축 방식이에요: ${name}`);
        let text;
        if (data[0] === 0xff && data[1] === 0xfe) {
          text = new TextDecoder("utf-16le").decode(data.subarray(2));
        } else if (data[0] === 0xfe && data[1] === 0xff) {
          const swapped = data.slice(2);
          for (let offset = 0; offset + 1 < swapped.length; offset += 2) {
            const first = swapped[offset];
            swapped[offset] = swapped[offset + 1];
            swapped[offset + 1] = first;
          }
          text = new TextDecoder("utf-16le").decode(swapped);
        } else {
          text = decoder.decode(data);
        }
        files.push({ name, text });
      }
      centralOffset += 46 + nameLength + extraLength + commentLength;
    }
    if (!files.length) throw new Error("ZIP 안에 TXT 메모 파일이 없어요");
    return files;
  }

  function normalizedBuilderMemoText(value) {
    return String(value || "").replace(/\r\n?/g, "\n").trim();
  }


  function builderMemoId(prefix) {
    try {
      return `${prefix}-${crypto.randomUUID()}`;
    } catch {
      return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 9)}`;
    }
  }

  function builderMemoWork(layout = null, create = true) {
    const storyId = builderStoryId();
    if (!storyId) return null;
    let work = builderNotes[storyId];
    if ((!work || typeof work !== "object") && create) {
      work = { title: "", categories: [], updatedAt: Date.now() };
      builderNotes[storyId] = work;
    }
    if (!work) return null;
    if (!Array.isArray(work.categories)) work.categories = [];
    if (!Array.isArray(work.promptPins)) work.promptPins = [];
    work.promptPins = work.promptPins.filter((pin) => pin && typeof pin === "object").map((pin) => {
      if (!pin.id) pin.id = builderMemoId("prompt-pin");
      pin.name = String(pin.name || "이름 없는 핀포인트");
      pin.start = Math.max(0, Number(pin.start || 0));
      pin.end = Math.max(pin.start, Number(pin.end || pin.start));
      pin.quote = String(pin.quote || "");
      return pin;
    });
    work.categories = work.categories.filter((category) => category && typeof category === "object").map((category) => {
      if (!category.id) category.id = builderMemoId("category");
      category.name = String(category.name || "이름 없는 카테고리");
      if (!Array.isArray(category.notes)) category.notes = [];
      category.notes = category.notes.filter((note) => note && typeof note === "object").map((note) => {
        if (!note.id) note.id = builderMemoId("note");
        note.text = String(note.text || "");
        return note;
      });
      return category;
    });

    const titleInput = Array.from(layout?.leftPane?.querySelectorAll("input") || []).find((input) =>
      String(input.getAttribute("placeholder") || "").includes("스토리의 이름")
    ) || (document.documentElement.dataset.ucbFixture === "builder"
      ? layout?.leftPane?.querySelector("input") : null);
    const visibleTitle = String(titleInput?.value || "").trim();
    if (visibleTitle && visibleTitle !== work.title) {
      work.title = visibleTitle;
      work.updatedAt = Date.now();
      persistBuilderNotes();
    }
    return { storyId, work };
  }

  function activeBuilderMemoCategory(storyId, work) {
    const selected = builderMemoActiveCategories.get(storyId);
    const active = work.categories.find((category) => category.id === selected) || work.categories[0] || null;
    if (active) builderMemoActiveCategories.set(storyId, active.id);
    else builderMemoActiveCategories.delete(storyId);
    return active;
  }

  function builderMemoStatus(storyId, text, state = "") {
    builderMemoStatuses.set(storyId, { text, state });
    const panel = document.querySelector(`.ucb-builder-memo-panel[data-story-id="${CSS.escape(storyId)}"]`);
    const status = panel?.querySelector("[data-builder-memo-status]");
    if (status) {
      status.dataset.state = state;
      setBuilderText(status, text);
    }
  }

  function serializeBuilderMemoCategory(category) {
    const notes = category.notes.map((note) => `\{\n${String(note.text || "")}\n\}`).join("\n,\n");
    return `[${category.name}]${notes ? `\n${notes}` : ""}`;
  }

  function serializeBuilderMemos(categories) {
    return categories.map(serializeBuilderMemoCategory).join("\n\n");
  }

  function parseBuilderMemoText(value) {
    const lines = String(value || "").replace(/^\uFEFF/, "").replace(/\r\n?/g, "\n").split("\n");
    const groups = [];
    let current = null;
    let noteLines = null;
    const nextMeaningful = (start) => {
      for (let index = start; index < lines.length; index += 1) {
        const text = lines[index].trim();
        if (text) return text;
      }
      return "";
    };

    for (let index = 0; index < lines.length; index += 1) {
      const line = lines[index];
      const trimmed = line.trim();
      if (noteLines) {
        if (trimmed === "}") {
          const next = nextMeaningful(index + 1);
          if (!next || next === "," || /^\[.*\]$/.test(next)) {
            current.notes.push(noteLines.join("\n"));
            noteLines = null;
            continue;
          }
        }
        noteLines.push(line);
        continue;
      }
      const categoryMatch = trimmed.match(/^\[(.+)]$/);
      if (categoryMatch) {
        current = { name: categoryMatch[1].trim(), notes: [] };
        groups.push(current);
        continue;
      }
      if (trimmed === "{" && current) noteLines = [];
    }
    if (noteLines) throw new Error("닫히지 않은 메모 블록이 있어요");
    if (!groups.length) throw new Error("[카테고리] 형식의 메모를 찾지 못했어요");
    return groups;
  }

  function builderMemoCategoryFromFileName(name) {
    const fileName = String(name || "").replace(/\\/g, "/").split("/").pop() || "";
    const base = fileName.replace(/\.txt$/i, "").trim();
    const exported = base.match(/_메모_\[([^\]]+)]$/);
    return String(exported?.[1] || base || "불러온 메모").trim();
  }

  function parseBuilderMemoImportFile(file) {
    const text = String(file?.text || "").replace(/^\uFEFF/, "").replace(/\r\n?/g, "\n").trim();
    if (!text) throw new Error(`비어 있는 TXT 파일이에요: ${file?.name || "이름 없음"}`);
    try {
      return parseBuilderMemoText(text);
    } catch {
      return [{ name: builderMemoCategoryFromFileName(file?.name), notes: [text] }];
    }
  }

  function mergeBuilderMemoGroups(storyId, work, groups) {
    const categoryKey = (value) => String(value || "").normalize("NFC").replace(/\s+/g, " ").trim();
    const appliedCategoryIds = new Set();
    let newCategoryCount = 0;
    let noteCount = 0;
    let firstImportedCategoryId = "";
    for (const group of groups) {
      const name = categoryKey(group.name);
      if (!name) continue;
      let category = work.categories.find((item) => categoryKey(item.name) === name);
      if (!category) {
        category = { id: builderMemoId("category"), name, notes: [], createdAt: Date.now() };
        work.categories.push(category);
        newCategoryCount += 1;
      }
      if (!firstImportedCategoryId) firstImportedCategoryId = category.id;
      appliedCategoryIds.add(category.id);
      for (const text of group.notes || []) {
        category.notes.push({ id: builderMemoId("note"), text: String(text), createdAt: Date.now(), updatedAt: Date.now() });
        noteCount += 1;
      }
    }
    if (firstImportedCategoryId) builderMemoActiveCategories.set(storyId, firstImportedCategoryId);
    work.updatedAt = Date.now();
    persistBuilderNotes(true);
    return { categoryCount: appliedCategoryIds.size, newCategoryCount, noteCount };
  }

  function builderMemoFileBase(storyId, work) {
    return safeExportName(work.title || `스토리_${storyId.slice(0, 8)}`);
  }

  function exportAllBuilderMemos(storyId, work) {
    if (!work.categories.some((category) => category.notes.length)) {
      builderMemoStatus(storyId, "내보낼 메모가 없어요", "error");
      return;
    }
    const blob = new Blob([`\uFEFF${serializeBuilderMemos(work.categories)}`], { type: "text/plain;charset=utf-8" });
    downloadBlob(blob, `${builderMemoFileBase(storyId, work)}_메모_전체.txt`);
    builderMemoStatus(storyId, "모든 메모를 TXT로 내보냈어요", "complete");
  }

  async function exportBuilderMemoCategories(storyId, work) {
    if (!work.categories.some((category) => category.notes.length)) {
      builderMemoStatus(storyId, "내보낼 메모가 없어요", "error");
      return;
    }
    try {
      builderMemoStatus(storyId, "카테고리별 파일을 묶는 중…");
      const base = builderMemoFileBase(storyId, work);
      const files = work.categories.map((category) => ({
        name: `${base}_메모_[${safeExportName(category.name)}].txt`,
        blob: new Blob([`\uFEFF${serializeBuilderMemoCategory(category)}`], { type: "text/plain;charset=utf-8" })
      }));
      const zip = await createStoredZip(files);
      downloadBlob(zip, `${base}_메모_카테고리별.zip`);
      builderMemoStatus(storyId, `카테고리 ${files.length}개를 ZIP으로 내보냈어요`, "complete");
    } catch (error) {
      builderMemoStatus(storyId, error?.message || "ZIP 내보내기에 실패했어요", "error");
    }
  }

  async function importBuilderMemoFile(file, storyId, work) {
    try {
      builderMemoStatus(storyId, "메모 파일을 읽는 중…");
      const groups = [];
      let importedFileCount = 1;
      if (/\.zip$/i.test(file.name) || file.type === "application/zip") {
        const files = await readZipTextFiles(file);
        importedFileCount = files.length;
        for (const item of files) groups.push(...parseBuilderMemoImportFile(item));
      } else {
        groups.push(...parseBuilderMemoImportFile({ name: file.name, text: await file.text() }));
      }
      const result = mergeBuilderMemoGroups(storyId, work, groups);
      renderBuilderMemoPanel(document.querySelector(".ucb-builder-memo-panel"), storyId, work, true);
      const created = result.newCategoryCount ? ` · 새 카테고리 ${result.newCategoryCount}개` : "";
      builderMemoStatus(storyId,
        `TXT ${importedFileCount}개의 실제 본문에서 메모 ${result.noteCount}개를 합쳤어요${created}`,
        "complete");
    } catch (error) {
      builderMemoStatus(storyId, error?.message || "메모를 불러오지 못했어요", "error");
    }
  }

  function autoSizeBuilderMemo(textarea) {
    if (!textarea) return;
    textarea.style.height = "0px";
    textarea.style.height = `${Math.min(520, Math.max(112, textarea.scrollHeight))}px`;
  }

  function createBuilderMemoPanel() {
    const panel = document.createElement("section");
    panel.className = "ucb-builder-memo-panel";
    panel.dataset.ucbBuilderReady = "false";
    panel.innerHTML = `
      <div class="ucb-builder-memo-main">
        <header class="ucb-builder-memo-head">
          <div><strong>제작 메모</strong><span data-builder-memo-work></span></div>
        </header>
        <form class="ucb-builder-memo-create" data-builder-memo-note-form>
          <textarea maxlength="12000" placeholder="현재 카테고리에 새 메모를 입력하세요" data-builder-memo-new-note></textarea>
          <button type="submit">메모 추가</button>
        </form>
        <div class="ucb-builder-memo-status" data-builder-memo-status></div>
        <div class="ucb-builder-memo-empty" data-builder-memo-empty></div>
        <div class="ucb-builder-memo-list" data-builder-memo-list></div>
      </div>
      <aside class="ucb-builder-memo-categories">
        <header><strong>카테고리</strong><span data-builder-memo-category-count></span></header>
        <form class="ucb-builder-memo-category-form" data-builder-memo-category-form>
          <input maxlength="40" placeholder="카테고리 이름" data-builder-memo-new-category>
          <button type="submit" aria-label="카테고리 추가">+</button>
        </form>
        <div class="ucb-builder-memo-category-list" data-builder-memo-category-list></div>
        <footer class="ucb-builder-memo-actions">
          <button type="button" data-builder-memo-export-all>전체 메모 내보내기</button>
          <button type="button" data-builder-memo-export-categories>개별 내보내기 · ZIP</button>
          <button type="button" data-builder-memo-import>메모 불러오기</button>
          <input type="file" accept=".txt,.zip,text/plain,application/zip" hidden data-builder-memo-file>
          <small>이 작품에만 연결되며 서버에는 등록되지 않아요.</small>
        </footer>
      </aside>
    `;

    panel.addEventListener("submit", (event) => {
      event.preventDefault();
      const context = builderMemoWork(null, true);
      if (!context || context.storyId !== panel.dataset.storyId) return;
      const { storyId, work } = context;
      if (event.target.matches("[data-builder-memo-category-form]")) {
        const input = event.target.querySelector("[data-builder-memo-new-category]");
        const name = String(input.value || "").trim();
        if (!name) {
          builderMemoStatus(storyId, "카테고리 이름을 입력해 주세요", "error");
          return;
        }
        if (work.categories.some((category) => category.name === name)) {
          builderMemoStatus(storyId, "같은 이름의 카테고리가 이미 있어요", "error");
          return;
        }
        const category = { id: builderMemoId("category"), name, notes: [], createdAt: Date.now() };
        work.categories.push(category);
        work.updatedAt = Date.now();
        builderMemoActiveCategories.set(storyId, category.id);
        input.value = "";
        persistBuilderNotes(true);
        renderBuilderMemoPanel(panel, storyId, work, true);
        builderMemoStatus(storyId, `‘${name}’ 카테고리를 만들었어요`, "complete");
        return;
      }
      if (event.target.matches("[data-builder-memo-note-form]")) {
        const category = activeBuilderMemoCategory(storyId, work);
        const textarea = event.target.querySelector("[data-builder-memo-new-note]");
        const text = String(textarea.value || "").trim();
        if (!category) {
          builderMemoStatus(storyId, "먼저 카테고리를 만들어 주세요", "error");
          return;
        }
        if (!text) {
          builderMemoStatus(storyId, "메모 내용을 입력해 주세요", "error");
          return;
        }
        category.notes.push({ id: builderMemoId("note"), text, createdAt: Date.now(), updatedAt: Date.now() });
        work.updatedAt = Date.now();
        textarea.value = "";
        persistBuilderNotes(true);
        renderBuilderMemoPanel(panel, storyId, work, true);
        builderMemoStatus(storyId, "메모를 저장했어요", "complete");
      }
    });

    panel.addEventListener("click", (event) => {
      const button = event.target.closest("button");
      if (!button) return;
      const context = builderMemoWork(null, true);
      if (!context || context.storyId !== panel.dataset.storyId) return;
      const { storyId, work } = context;
      const selectId = button.dataset.builderMemoSelectCategory;
      if (selectId) {
        builderMemoActiveCategories.set(storyId, selectId);
        renderBuilderMemoPanel(panel, storyId, work, true);
        return;
      }
      const deleteCategoryId = button.dataset.builderMemoDeleteCategory;
      if (deleteCategoryId) {
        const category = work.categories.find((item) => item.id === deleteCategoryId);
        if (!category || !confirm(`‘${category.name}’ 카테고리와 메모를 모두 삭제할까요?`)) return;
        work.categories = work.categories.filter((item) => item.id !== deleteCategoryId);
        builderMemoActiveCategories.delete(storyId);
        work.updatedAt = Date.now();
        persistBuilderNotes(true);
        renderBuilderMemoPanel(panel, storyId, work, true);
        builderMemoStatus(storyId, "카테고리를 삭제했어요", "complete");
        return;
      }
      const deleteNoteId = button.dataset.builderMemoDeleteNote;
      if (deleteNoteId) {
        const category = activeBuilderMemoCategory(storyId, work);
        if (!category || !confirm("이 메모를 삭제할까요?")) return;
        category.notes = category.notes.filter((note) => note.id !== deleteNoteId);
        work.updatedAt = Date.now();
        persistBuilderNotes(true);
        renderBuilderMemoPanel(panel, storyId, work, true);
        builderMemoStatus(storyId, "메모를 삭제했어요", "complete");
        return;
      }
      if (button.hasAttribute("data-builder-memo-export-all")) exportAllBuilderMemos(storyId, work);
      if (button.hasAttribute("data-builder-memo-export-categories")) void exportBuilderMemoCategories(storyId, work);
      if (button.hasAttribute("data-builder-memo-import")) panel.querySelector("[data-builder-memo-file]")?.click();
    });

    panel.addEventListener("input", (event) => {
      const noteId = event.target.dataset.builderMemoNoteId;
      if (!noteId) return;
      const context = builderMemoWork(null, true);
      if (!context || context.storyId !== panel.dataset.storyId) return;
      const category = activeBuilderMemoCategory(context.storyId, context.work);
      const note = category?.notes.find((item) => item.id === noteId);
      if (!note) return;
      note.text = event.target.value;
      note.updatedAt = Date.now();
      context.work.updatedAt = Date.now();
      autoSizeBuilderMemo(event.target);
      persistBuilderNotes();
      builderMemoStatus(context.storyId, "입력한 내용은 자동 저장돼요");
    });

    panel.querySelector("[data-builder-memo-file]").addEventListener("change", (event) => {
      const file = event.target.files?.[0];
      const context = builderMemoWork(null, true);
      event.target.value = "";
      if (file && context && context.storyId === panel.dataset.storyId) {
        void importBuilderMemoFile(file, context.storyId, context.work);
      }
    });
    return panel;
  }

  function renderBuilderMemoPanel(panel, storyId, work, force = false) {
    if (!panel) return;
    const active = activeBuilderMemoCategory(storyId, work);
    const structureKey = `${storyId}|${active?.id || ""}|${work.categories.map((category) =>
      `${category.id}:${category.name}:${category.notes.map((note) => note.id).join(",")}`).join("|")}`;
    panel.dataset.storyId = storyId;
    setBuilderText(panel.querySelector("[data-builder-memo-work]"), work.title || `작품 ${storyId.slice(0, 8)}`);
    setBuilderText(panel.querySelector("[data-builder-memo-category-count]"), `${work.categories.length}개`);
    const savedStatus = builderMemoStatuses.get(storyId) || { text: "서버와 무관한 로컬 메모 공간입니다", state: "" };
    const status = panel.querySelector("[data-builder-memo-status]");
    status.dataset.state = savedStatus.state;
    setBuilderText(status, savedStatus.text);
    if (!force && panel.dataset.renderKey === structureKey) return;
    panel.dataset.renderKey = structureKey;

    const categoryList = panel.querySelector("[data-builder-memo-category-list]");
    categoryList.replaceChildren(...work.categories.map((category) => {
      const row = document.createElement("div");
      row.className = "ucb-builder-memo-category-row";
      row.dataset.active = String(category.id === active?.id);
      const select = document.createElement("button");
      select.type = "button";
      select.className = "ucb-builder-memo-category";
      select.dataset.builderMemoSelectCategory = category.id;
      const name = document.createElement("span");
      name.textContent = category.name;
      const count = document.createElement("small");
      count.textContent = String(category.notes.length);
      select.append(name, count);
      const remove = document.createElement("button");
      remove.type = "button";
      remove.className = "ucb-builder-memo-remove";
      remove.dataset.builderMemoDeleteCategory = category.id;
      remove.setAttribute("aria-label", `${category.name} 카테고리 삭제`);
      remove.textContent = "×";
      row.append(select, remove);
      return row;
    }));

    const noteForm = panel.querySelector("[data-builder-memo-note-form]");
    noteForm.querySelector("textarea").disabled = !active;
    noteForm.querySelector("button").disabled = !active;
    const empty = panel.querySelector("[data-builder-memo-empty]");
    setBuilderText(empty, !active ? "오른쪽에서 카테고리를 먼저 만들어 주세요."
      : !active.notes.length ? `‘${active.name}’에 아직 메모가 없어요.` : "");
    empty.hidden = Boolean(active?.notes.length);

    const list = panel.querySelector("[data-builder-memo-list]");
    list.replaceChildren(...(active?.notes || []).map((note, index) => {
      const card = document.createElement("article");
      card.className = "ucb-builder-memo-card";
      const head = document.createElement("header");
      const label = document.createElement("span");
      label.textContent = `메모 ${String(index + 1).padStart(2, "0")}`;
      const remove = document.createElement("button");
      remove.type = "button";
      remove.dataset.builderMemoDeleteNote = note.id;
      remove.textContent = "삭제";
      head.append(label, remove);
      const textarea = document.createElement("textarea");
      textarea.dataset.builderMemoNoteId = note.id;
      textarea.maxLength = 12000;
      textarea.value = note.text;
      card.append(head, textarea);
      requestAnimationFrame(() => autoSizeBuilderMemo(textarea));
      return card;
    }));
  }

  function updateBuilderMemoPanel(layout, mode, open) {
    let panel = document.querySelector(".ucb-builder-memo-panel");
    if (!panel) {
      panel = createBuilderMemoPanel();
      document.documentElement.append(panel);
    }
    const context = builderMemoWork(layout, true);
    if (!context) {
      panel.dataset.ucbBuilderReady = "false";
      return;
    }
    const layoutRect = layout.layout.getBoundingClientRect();
    const rightRect = layout.rightPane.getBoundingClientRect();
    const memoWidth = mode === "memo"
      ? Math.min(640, Math.max(560, innerWidth - 720))
      : rightRect.width;
    panel.style.setProperty("--ucb-builder-memo-top", `${Math.max(0, Math.round(layoutRect.top))}px`);
    panel.style.setProperty("--ucb-builder-memo-width", `${Math.max(360, Math.round(memoWidth))}px`);
    panel.dataset.mode = mode;
    panel.dataset.open = String(mode === "memo" && open);
    panel.dataset.ucbBuilderReady = "true";
    renderBuilderMemoPanel(panel, context.storyId, context.work);
  }

  function currentBuilderPromptTextarea(layout) {
    if (activeBuilderStep(layout) !== "스토리 설정") return null;
    const textareas = visibleBuilderControls(layout?.leftPane, "textarea");
    return textareas.find((textarea) => Number(textarea.maxLength) === 7000) ||
      textareas.sort((a, b) => b.getBoundingClientRect().height - a.getBoundingClientRect().height)[0] || null;
  }

  function builderPromptField(textarea, form) {
    let field = textarea?.parentElement || null;
    let candidate = field;
    while (field && field !== form) {
      const text = String(field.textContent || "").replace(/\s+/g, " ");
      if (text.includes("프롬프트 템플릿")) break;
      if (text.includes("AI에게 지시할 내용을") && field.querySelectorAll("textarea").length === 1) {
        candidate = field;
      }
      field = field.parentElement;
    }
    return candidate;
  }

  function builderPromptPinStatus(panel, text, state = "") {
    const status = panel?.querySelector("[data-builder-prompt-pin-status]");
    if (!status) return;
    status.dataset.state = state;
    setBuilderText(status, text);
  }

  function resolveBuilderPromptPinRange(pin, text) {
    const length = text.length;
    const start = Math.max(0, Math.min(length, Number(pin.start || 0)));
    const end = Math.max(start, Math.min(length, Number(pin.end || start)));
    if (!pin.quote || text.slice(start, end) === pin.quote) return { start, end };

    let best = -1;
    let distance = Infinity;
    for (let index = text.indexOf(pin.quote); index >= 0; index = text.indexOf(pin.quote, index + 1)) {
      const nextDistance = Math.abs(index - start);
      if (nextDistance < distance) {
        best = index;
        distance = nextDistance;
      }
    }
    return best >= 0 ? { start: best, end: best + pin.quote.length } : { start, end };
  }

  function jumpToBuilderPromptPin(panel, pin) {
    const layout = findBuilderLayout();
    const textarea = currentBuilderPromptTextarea(layout);
    if (!textarea) {
      builderPromptPinStatus(panel, "스토리 설정의 프롬프트 편집기를 열어 주세요", "error");
      return;
    }
    const range = resolveBuilderPromptPinRange(pin, textarea.value);
    pin.start = range.start;
    pin.end = range.end;
    if (range.end > range.start) pin.quote = textarea.value.slice(range.start, range.end);
    textarea.scrollIntoView({ block: "center", behavior: "smooth" });
    textarea.focus({ preventScroll: true });
    textarea.setSelectionRange(range.start, range.end, "forward");
    const beforeLines = textarea.value.slice(0, range.start).split("\n").length - 1;
    const totalLines = Math.max(1, textarea.value.split("\n").length - 1);
    textarea.scrollTop = Math.max(0, textarea.scrollHeight - textarea.clientHeight) * (beforeLines / totalLines);
    builderPromptPinStatus(panel, `‘${pin.name}’ 위치로 이동했어요`, "complete");
  }

  function renderBuilderPromptPins(panel, storyId, work) {
    if (!panel) return;
    panel.dataset.storyId = storyId;
    setBuilderText(panel.querySelector("[data-builder-prompt-pin-count]"), `${work.promptPins.length}개`);
    const renderKey = `${storyId}|${work.promptPins.map((pin) =>
      `${pin.id}:${pin.name}:${pin.start}:${pin.end}:${pin.quote}`).join("|")}`;
    if (panel.dataset.renderKey === renderKey) return;
    panel.dataset.renderKey = renderKey;
    const list = panel.querySelector("[data-builder-prompt-pin-list]");
    list.replaceChildren(...work.promptPins.map((pin, index) => {
      const row = document.createElement("div");
      row.className = "ucb-builder-prompt-pin-row";
      const jump = document.createElement("button");
      jump.type = "button";
      jump.className = "ucb-builder-prompt-pin-jump";
      jump.dataset.builderPromptPinJump = pin.id;
      const name = document.createElement("strong");
      name.textContent = pin.name;
      const quote = document.createElement("span");
      quote.textContent = pin.quote.replace(/\s+/g, " ").trim().slice(0, 80) || `위치 ${pin.start.toLocaleString("ko-KR")}`;
      jump.append(name, quote);
      const rename = document.createElement("button");
      rename.type = "button";
      rename.className = "ucb-builder-prompt-pin-subaction";
      rename.dataset.builderPromptPinRename = pin.id;
      rename.textContent = "이름";
      rename.setAttribute("aria-label", `${pin.name} 이름 변경`);
      const remove = document.createElement("button");
      remove.type = "button";
      remove.className = "ucb-builder-prompt-pin-subaction ucb-builder-prompt-pin-remove";
      remove.dataset.builderPromptPinDelete = pin.id;
      remove.textContent = "삭제";
      remove.setAttribute("aria-label", `${pin.name} 핀포인트 삭제`);
      row.dataset.index = String(index);
      row.append(jump, rename, remove);
      return row;
    }));
    list.hidden = work.promptPins.length === 0;
  }

  function createBuilderPromptPinsPanel() {
    const panel = document.createElement("section");
    panel.className = "ucb-builder-prompt-pins";
    panel.innerHTML = `
      <header>
        <div><strong>프롬프트 핀포인트</strong><small>프롬프트의 텍스트를 드래그한 뒤 이름을 붙여 저장하세요.</small></div>
        <span data-builder-prompt-pin-count>0개</span>
      </header>
      <form data-builder-prompt-pin-form>
        <input maxlength="40" placeholder="핀포인트 이름 (선택)" data-builder-prompt-pin-name>
        <button type="submit">선택 영역 추가</button>
      </form>
      <div class="ucb-builder-prompt-pin-status" data-builder-prompt-pin-status>저장한 핀을 누르면 해당 부분을 바로 선택합니다.</div>
      <div class="ucb-builder-prompt-pin-list" data-builder-prompt-pin-list hidden></div>
    `;
    panel.addEventListener("submit", (event) => {
      event.preventDefault();
      const layout = findBuilderLayout();
      const textarea = currentBuilderPromptTextarea(layout);
      const context = builderMemoWork(layout, true);
      if (!textarea || !context || context.storyId !== panel.dataset.storyId) return;
      const start = textarea.selectionStart;
      const end = textarea.selectionEnd;
      const quote = textarea.value.slice(start, end);
      if (start === end || !quote.trim()) {
        builderPromptPinStatus(panel, "먼저 프롬프트에서 저장할 텍스트를 드래그해 주세요", "error");
        return;
      }
      const nameInput = panel.querySelector("[data-builder-prompt-pin-name]");
      const fallback = quote.replace(/\s+/g, " ").trim().slice(0, 24) || `핀포인트 ${context.work.promptPins.length + 1}`;
      context.work.promptPins.push({
        id: builderMemoId("prompt-pin"),
        name: String(nameInput.value || "").trim() || fallback,
        start,
        end,
        quote,
        createdAt: Date.now(),
        updatedAt: Date.now()
      });
      context.work.updatedAt = Date.now();
      nameInput.value = "";
      persistBuilderNotes(true);
      renderBuilderPromptPins(panel, context.storyId, context.work);
      builderPromptPinStatus(panel, "선택 영역을 핀포인트로 저장했어요", "complete");
    });
    panel.addEventListener("click", (event) => {
      const button = event.target.closest("button");
      if (!button || button.type === "submit") return;
      const layout = findBuilderLayout();
      const context = builderMemoWork(layout, true);
      if (!context || context.storyId !== panel.dataset.storyId) return;
      const pinId = button.dataset.builderPromptPinJump || button.dataset.builderPromptPinRename ||
        button.dataset.builderPromptPinDelete;
      const pin = context.work.promptPins.find((item) => item.id === pinId);
      if (!pin) return;
      if (button.dataset.builderPromptPinJump) {
        jumpToBuilderPromptPin(panel, pin);
        persistBuilderNotes();
        return;
      }
      if (button.dataset.builderPromptPinRename) {
        const name = prompt("핀포인트 이름", pin.name);
        if (name === null || !name.trim()) return;
        pin.name = name.trim();
        pin.updatedAt = Date.now();
        context.work.updatedAt = Date.now();
        persistBuilderNotes(true);
        renderBuilderPromptPins(panel, context.storyId, context.work);
        builderPromptPinStatus(panel, "핀포인트 이름을 변경했어요", "complete");
        return;
      }
      if (button.dataset.builderPromptPinDelete) {
        context.work.promptPins = context.work.promptPins.filter((item) => item.id !== pin.id);
        context.work.updatedAt = Date.now();
        persistBuilderNotes(true);
        renderBuilderPromptPins(panel, context.storyId, context.work);
        builderPromptPinStatus(panel, "핀포인트를 삭제했어요", "complete");
      }
    });
    return panel;
  }

  function ensureBuilderPromptPins(layout) {
    const textarea = currentBuilderPromptTextarea(layout);
    if (!textarea) {
      document.querySelector(".ucb-builder-prompt-pins")?.remove();
      return;
    }
    textarea.dataset.ucbBuilderPrompt = "true";
    const shell = textarea.parentElement;
    if (shell) shell.dataset.ucbBuilderPromptShell = "true";
    const field = builderPromptField(textarea, layout.form);
    if (!field) return;
    field.dataset.ucbBuilderPromptField = "true";

    let panel = document.querySelector(".ucb-builder-prompt-pins");
    if (!panel) panel = createBuilderPromptPinsPanel();
    if (panel.previousElementSibling !== field) field.insertAdjacentElement("afterend", panel);
    const context = builderMemoWork(layout, true);
    if (!context) return;
    if (!builderPromptLastValues.has(context.storyId)) builderPromptLastValues.set(context.storyId, textarea.value);
    renderBuilderPromptPins(panel, context.storyId, context.work);
  }

  function updateBuilderPromptPinsForInput(layout, textarea) {
    const context = builderMemoWork(layout, true);
    if (!context) return;
    const previous = builderPromptLastValues.get(context.storyId);
    const next = textarea.value;
    builderPromptLastValues.set(context.storyId, next);
    if (previous === undefined || previous === next || !context.work.promptPins.length) return;

    let prefix = 0;
    while (prefix < previous.length && prefix < next.length && previous[prefix] === next[prefix]) prefix += 1;
    let oldTail = previous.length;
    let newTail = next.length;
    while (oldTail > prefix && newTail > prefix && previous[oldTail - 1] === next[newTail - 1]) {
      oldTail -= 1;
      newTail -= 1;
    }
    const delta = (newTail - prefix) - (oldTail - prefix);
    for (const pin of context.work.promptPins) {
      if (pin.end <= prefix) continue;
      if (pin.start >= oldTail) {
        pin.start = Math.max(0, pin.start + delta);
        pin.end = Math.max(pin.start, pin.end + delta);
      } else {
        pin.start = Math.max(0, Math.min(pin.start, next.length));
        pin.end = Math.max(pin.start, Math.min(next.length, pin.end + delta));
      }
      pin.quote = next.slice(pin.start, pin.end);
      pin.updatedAt = Date.now();
    }
    context.work.updatedAt = Date.now();
    persistBuilderNotes();
    const panel = document.querySelector(".ucb-builder-prompt-pins");
    if (panel) renderBuilderPromptPins(panel, context.storyId, context.work);
  }

  function normalizedBuilderStep(value) {
    const text = String(value || "").replace(/\*/g, "").replace(/\s+/g, " ").trim();
    return BUILDER_STEPS.find((step) => text === step || text.startsWith(step)) || "";
  }

  function builderStepButtons(leftPane) {
    const result = new Map();
    for (const button of leftPane?.querySelectorAll("button") || []) {
      const step = normalizedBuilderStep(button.textContent);
      if (step && !result.has(step)) result.set(step, button);
    }
    return result;
  }

  function findBuilderLayout() {
    if (detectPage() !== "builder") return null;
    const form = document.querySelector(".build-scroll-form");
    if (!form) return null;

    let leftPane = form;
    let layout = null;
    let rightPane = null;
    for (let depth = 0; depth < 7 && leftPane.parentElement; depth += 1) {
      const parent = leftPane.parentElement;
      const leftWidth = Math.max(1, leftPane.getBoundingClientRect().width);
      const parentWidth = parent.getBoundingClientRect().width;
      const knownLayout = parent.dataset.ucbBuilderLayout === "true";
      const candidate = knownLayout || parentWidth > leftWidth * 1.35
        ? Array.from(parent.children)
          .filter((child) => child !== leftPane && !child.classList?.contains("ucb-builder-nav"))
          .filter((child) => {
            const rect = child.getBoundingClientRect();
            return child.dataset.ucbBuilderRight === "true" ||
              (rect.width > leftWidth * .4 && rect.height > 180);
          })
          .sort((a, b) => b.getBoundingClientRect().width - a.getBoundingClientRect().width)[0]
        : null;
      if (candidate) {
        layout = parent;
        rightPane = candidate;
        break;
      }
      leftPane = parent;
    }
    if (!layout || !rightPane) return null;

    const steps = builderStepButtons(leftPane);
    if (steps.size < 5) return null;
    const buttons = Array.from(steps.values());
    let common = buttons[0]?.parentElement || null;
    while (common && !buttons.every((button) => common.contains(button))) common = common.parentElement;
    let nativeNav = common;
    while (nativeNav?.parentElement && nativeNav.parentElement !== leftPane) {
      const currentHeight = nativeNav.getBoundingClientRect().height;
      const parentHeight = nativeNav.parentElement.getBoundingClientRect().height;
      if (parentHeight > 80 || parentHeight > currentHeight + 6) break;
      nativeNav = nativeNav.parentElement;
    }

    return {
      layout,
      leftPane,
      rightPane,
      form,
      formShell: form.parentElement,
      nativeNav,
      steps
    };
  }

  function activeBuilderStep(layout) {
    for (const [step, button] of layout?.steps || []) {
      const className = typeof button.className === "string" ? button.className : "";
      if (className.includes("border-primary") || button.getAttribute("aria-selected") === "true") return step;
    }
    return "";
  }

  function visibleBuilderButton(leftPane, label) {
    return Array.from(leftPane?.querySelectorAll("button") || []).find((button) => {
      const rect = button.getBoundingClientRect();
      return rect.width > 0 && rect.height > 0 && (button.textContent || "").replace(/\s+/g, " ").trim() === label;
    }) || null;
  }

  function resetBuilderStepTrackingIfNeeded() {
    const routeKey = `${builderStoryId()}|${location.pathname}|${new URLSearchParams(location.search).get("type") || ""}`;
    if (routeKey === builderStateRouteKey) return;
    builderStateRouteKey = routeKey;
    builderStepStates.clear();
    builderStepIssues.clear();
    builderStepBaselines.clear();
    builderStepSnapshots.clear();
    builderModifiedSteps.clear();
    builderPromptLastValues.clear();
    builderDirty = false;
    builderSaveState = "clean";
  }

  function visibleBuilderControls(root, selector) {
    return Array.from(root?.querySelectorAll(selector) || []).filter((element) => {
      const rect = element.getBoundingClientRect();
      return rect.width > 0 && rect.height > 0;
    });
  }

  function findBuilderRequiredControl(leftPane, field) {
    if (field.type === "text") {
      return visibleBuilderControls(leftPane, "input[placeholder], textarea[placeholder]").find((control) =>
        String(control.getAttribute("placeholder") || "").trim() === field.placeholder
      ) || null;
    }
    if (field.type === "prompt") {
      return visibleBuilderControls(leftPane, "textarea").find((control) => Number(control.maxLength) === 7000) ||
        visibleBuilderControls(leftPane, "textarea").sort((a, b) =>
          b.getBoundingClientRect().height - a.getBoundingClientRect().height
        )[0] || null;
    }
    if (field.type === "combobox") {
      return visibleBuilderControls(leftPane, '[role="combobox"]').at(field.index) || null;
    }
    if (field.type === "radiogroup") {
      return visibleBuilderControls(leftPane, '[role="radiogroup"]').find((group) =>
        String(group.textContent || "").replace(/\s+/g, " ").includes(field.includes)
      ) || null;
    }
    return null;
  }

  function builderRequiredControlValue(control, type) {
    if (!control) return "";
    if (type === "text") return String(control.value || "").trim();
    if (type === "radiogroup") {
      const checked = control.querySelector('[role="radio"][aria-checked="true"], input[type="radio"]:checked');
      if (!checked) return "";
      const value = checked.getAttribute("value");
      if (value && value !== "on") return value.trim();
      const labelled = checked.getAttribute("aria-label") || checked.closest("label")?.textContent ||
        checked.parentElement?.textContent || "선택됨";
      return String(labelled).replace(/\s+/g, " ").trim();
    }
    const value = "value" in control ? String(control.value || "") : "";
    return String(value || control.getAttribute("data-value") || control.getAttribute("aria-label") ||
      control.textContent || "").replace(/\s+/g, " ").trim();
  }

  function builderRequiredValueIsEmpty(value) {
    const normalized = String(value || "").replace(/\s+/g, " ").trim();
    return !normalized || /^(선택|미설정|설정 안 함|없음)$/.test(normalized) ||
      normalized.includes("선택해 주세요");
  }

  function captureRequiredBuilderStep(layout, step) {
    const specs = BUILDER_REQUIRED_FIELDS[step];
    if (!specs) return false;
    const fields = specs.map((field) => {
      const control = findBuilderRequiredControl(layout.leftPane, field);
      return { ...field, control, value: builderRequiredControlValue(control, field.type) };
    });
    if (fields.some((field) => !field.control)) {
      builderStepStates.set(step, "incomplete");
      builderStepIssues.set(step, "필수 입력란 확인 필요");
      return true;
    }

    const snapshot = JSON.stringify(Object.fromEntries(fields.map((field) => [field.key, field.value])));
    if (!builderStepBaselines.has(step)) builderStepBaselines.set(step, snapshot);
    builderStepSnapshots.set(step, snapshot);

    const missing = fields.filter((field) => builderRequiredValueIsEmpty(field.value)).map((field) => field.label);
    if (missing.length) {
      builderStepStates.set(step, "incomplete");
      builderStepIssues.set(step, `${missing.join(", ")} 확인 필요`);
    } else if (snapshot !== builderStepBaselines.get(step)) {
      builderStepStates.set(step, "modified");
      builderStepIssues.set(step, "저장된 값과 다름");
    } else {
      builderStepStates.set(step, "complete");
      builderStepIssues.delete(step);
    }
    return true;
  }

  function commitBuilderStepSnapshots() {
    for (const [step, snapshot] of builderStepSnapshots) builderStepBaselines.set(step, snapshot);
    builderModifiedSteps.clear();
  }

  function captureBuilderStepState(layout = findBuilderLayout()) {
    if (!layout) return;
    resetBuilderStepTrackingIfNeeded();
    const step = activeBuilderStep(layout);
    const original = layout.steps.get(step);
    if (!step || !original) return;
    if (captureRequiredBuilderStep(layout, step)) return;
    const required = (original.textContent || "").includes("*");
    const invalid = Boolean(layout.leftPane.querySelector('[aria-invalid="true"], [data-invalid="true"]'));
    const next = visibleBuilderButton(layout.leftPane, "다음");

    if (invalid || next?.disabled) builderStepStates.set(step, "incomplete");
    else if (builderModifiedSteps.has(step)) builderStepStates.set(step, "modified");
    else if (required) builderStepStates.set(step, "complete");
    else builderStepStates.set(step, "optional");
  }

  function setBuilderText(element, value) {
    if (element && element.textContent !== value) element.textContent = value;
  }

  function createBuilderNavigation() {
    const aside = document.createElement("aside");
    aside.className = "ucb-builder-nav";
    aside.dataset.ucbBuilderReady = "false";
    aside.innerHTML = `
      <div class="ucb-builder-nav-head">
        <strong>편집 단계</strong>
        <span class="ucb-builder-progress"></span>
      </div>
      <div class="ucb-builder-save-state" data-state="clean"></div>
      <nav class="ucb-builder-step-list" aria-label="스토리 편집 단계"></nav>
      <button class="ucb-builder-preview-toggle" type="button"></button>
    `;
    const list = aside.querySelector(".ucb-builder-step-list");
    BUILDER_STEPS.forEach((step, index) => {
      const button = document.createElement("button");
      button.type = "button";
      button.className = "ucb-builder-step";
      button.dataset.step = step;
      button.innerHTML = `
        <span class="ucb-builder-step-index">${String(index + 1).padStart(2, "0")}</span>
        <span class="ucb-builder-step-label"></span>
        <span class="ucb-builder-step-state"></span>
      `;
      button.querySelector(".ucb-builder-step-label").textContent = step;
      button.addEventListener("click", () => {
        const current = findBuilderLayout();
        if (!current) return;
        captureBuilderStepState(current);
        current.steps.get(step)?.click();
        scheduleScan();
      });
      list.append(button);
    });
    aside.querySelector(".ucb-builder-preview-toggle").addEventListener("click", () => {
      const current = findBuilderLayout();
      if (!current || current.layout.dataset.ucbBuilderPreviewAvailable !== "true") return;
      const mode = current.layout.dataset.ucbBuilderMode === "memo" ? "memo" : "preview";
      const key = mode === "memo" ? "builderMemo" : "builderPreview";
      settings = { ...settings, [key]: !settings[key] };
      persistSettings();
      applySettings();
      scheduleScan();
    });
    return aside;
  }

  function updateBuilderNavigation(layout, rightAvailable, mode) {
    let aside = document.querySelector(".ucb-builder-nav");
    if (!aside) {
      aside = createBuilderNavigation();
      document.documentElement.append(aside);
    }

    const layoutTop = Math.max(0, Math.round(layout.layout.getBoundingClientRect().top));
    aside.style.setProperty("--ucb-builder-nav-top", `${layoutTop}px`);
    aside.dataset.ucbBuilderReady = "true";

    const active = activeBuilderStep(layout);
    const activeIndex = Math.max(0, BUILDER_STEPS.indexOf(active));
    setBuilderText(aside.querySelector(".ucb-builder-progress"), `${activeIndex + 1} / ${BUILDER_STEPS.length}`);
    const saveState = aside.querySelector(".ucb-builder-save-state");
    saveState.dataset.state = builderDirty ? "dirty" : builderSaveState;
    setBuilderText(saveState, builderDirty
      ? "저장하지 않은 변경사항"
      : builderSaveState === "requested" ? "저장을 요청했어요" : "변경사항 없음");

    aside.querySelectorAll(".ucb-builder-step").forEach((button) => {
      const step = button.dataset.step;
      const original = layout.steps.get(step);
      const required = Boolean(original && (original.textContent || "").includes("*"));
      const state = builderStepStates.get(step) || (required ? "required" : "optional");
      button.dataset.active = String(step === active);
      button.dataset.state = state;
      button.setAttribute("aria-current", step === active ? "step" : "false");
      const labels = {
        complete: "완료",
        incomplete: "확인 필요",
        modified: "수정됨",
        review: "최종 검토",
        required: "필수",
        optional: "선택"
      };
      setBuilderText(button.querySelector(".ucb-builder-step-state"), labels[state] || "선택");
      const issue = builderStepIssues.get(step);
      if (issue) button.title = issue;
      else button.removeAttribute("title");
    });

    const toggle = aside.querySelector(".ucb-builder-preview-toggle");
    const isMemo = mode === "memo";
    const open = isMemo ? settings.builderMemo : settings.builderPreview;
    toggle.disabled = !rightAvailable;
    toggle.dataset.open = String(rightAvailable && open);
    setBuilderText(toggle, !rightAvailable
      ? isMemo ? "넓은 화면에서 메모를 열 수 있어요" : "이 단계에는 미리보기가 없어요"
      : isMemo
        ? open ? "메모 접기" : "메모 열기"
        : open ? "미리보기 접기" : "미리보기 열기");
  }

  function markBuilderPreviewControls(rightPane) {
    rightPane.querySelectorAll("[data-ucb-builder-preview-tool], [data-ucb-builder-composer]").forEach((element) => {
      element.removeAttribute("data-ucb-builder-preview-tool");
      element.removeAttribute("data-ucb-builder-composer");
    });
    const editor = rightPane.querySelector('[contenteditable="true"] p[data-placeholder="메시지 보내기"], [contenteditable="true"]');
    if (editor) {
      let composer = editor.closest('[contenteditable="true"]') || editor;
      for (let depth = 0; depth < 8 && composer.parentElement && composer.parentElement !== rightPane; depth += 1) {
        const currentHeight = Math.max(1, composer.getBoundingClientRect().height);
        const parentHeight = composer.parentElement.getBoundingClientRect().height;
        if (parentHeight > Math.max(220, currentHeight * 2.2)) break;
        composer = composer.parentElement;
      }
      composer.dataset.ucbBuilderComposer = "true";
    }

    Array.from(rightPane.querySelectorAll("button")).forEach((button) => {
      if ((button.textContent || "").replace(/\s+/g, " ").trim() === "채팅 내역") {
        button.dataset.ucbBuilderPreviewTool = "true";
      }
    });
    const topCombobox = Array.from(rightPane.querySelectorAll('[role="combobox"]')).find((element) =>
      element.getBoundingClientRect().top < rightPane.getBoundingClientRect().top + 90
    );
    if (topCombobox) topCombobox.dataset.ucbBuilderPreviewTool = "true";
  }

  function markBuilderLayout() {
    if (detectPage() !== "builder") {
      document.querySelector(".ucb-builder-nav")?.remove();
      document.querySelector(".ucb-builder-memo-panel")?.remove();
      document.querySelector(".ucb-builder-prompt-pins")?.remove();
      return;
    }
    const layout = findBuilderLayout();
    if (!layout) {
      const aside = document.querySelector(".ucb-builder-nav");
      if (aside) aside.dataset.ucbBuilderReady = "false";
      const memo = document.querySelector(".ucb-builder-memo-panel");
      if (memo) memo.dataset.ucbBuilderReady = "false";
      return;
    }
    captureBuilderStepState(layout);

    layout.layout.dataset.ucbBuilderLayout = "true";
    layout.leftPane.dataset.ucbBuilderLeft = "true";
    layout.rightPane.dataset.ucbBuilderRight = "true";
    layout.form.dataset.ucbBuilderForm = "true";
    if (layout.formShell) layout.formShell.dataset.ucbBuilderFormShell = "true";
    if (layout.nativeNav) layout.nativeNav.dataset.ucbBuilderNativeNav = "true";

    const activeStep = activeBuilderStep(layout);
    const mode = activeStep === "등록" ? "preview" : "memo";
    const rightAvailable = mode === "preview" || innerWidth >= 1280;
    const rightOpen = rightAvailable && (mode === "memo" ? settings.builderMemo : settings.builderPreview);
    layout.layout.dataset.ucbBuilderMode = mode;
    layout.layout.dataset.ucbBuilderStep = activeStep;
    layout.layout.dataset.ucbBuilderPreviewAvailable = String(rightAvailable);
    layout.layout.dataset.ucbBuilderPreviewOpen = String(rightOpen);
    markBuilderPreviewControls(layout.rightPane);
    ensureBuilderPromptPins(layout);
    updateBuilderNavigation(layout, rightAvailable, mode);
    updateBuilderMemoPanel(layout, mode, rightOpen);

    Array.from(layout.leftPane.querySelectorAll("p")).forEach((paragraph) => {
      if ((paragraph.textContent || "").includes("민감한 스토리의 경우 제작 시 성인 인증이 필요해요")) {
        (paragraph.parentElement || paragraph).dataset.ucbBuilderNotice = "true";
      }
    });
  }

  function handleBuilderInput(event) {
    if (detectPage() !== "builder" || !event.target.closest?.('[data-ucb-builder-left="true"]')) return;
    if (event.target.closest?.(".ucb-builder-prompt-pins")) return;
    const layout = findBuilderLayout();
    const step = activeBuilderStep(layout);
    if (step) builderModifiedSteps.add(step);
    if (event.target.matches?.('textarea[data-ucb-builder-prompt="true"], textarea[maxlength="7000"]')) {
      updateBuilderPromptPinsForInput(layout, event.target);
    }
    builderDirty = true;
    builderSaveState = "dirty";
    captureBuilderStepState(layout);
    scheduleScan();
  }

  function handleBuilderClick(event) {
    if (detectPage() !== "builder") return;
    const button = event.target.closest?.("button");
    if (!button || button.closest(".ucb-builder-nav")) return;
    const text = (button.textContent || "").replace(/\s+/g, " ").trim();
    if (normalizedBuilderStep(text) || text === "이전" || text === "다음") {
      captureBuilderStepState();
    }
    if (text === "임시저장" || text === "수정") {
      builderDirty = false;
      builderSaveState = "requested";
      commitBuilderStepSnapshots();
      scheduleScan();
    }
    setTimeout(scheduleScan, 0);
  }


